-- SEO-STANDARD1 — Technical data enrichment for the six published standard pages.
--
-- Adds sourced grade tables (mechanical properties and chemical composition)
-- to each public standard page, comparison tables where two standards share
-- grades (EN 10210/EN 10219, EN 10216-2/EN 10217-2), two data-bearing FAQs and
-- the manufacturer standard pages used as evidence.
--
-- Editorial contract unchanged: values are attributed to manufacturer
-- datasheets, never presented as the normative text; no equivalence or
-- substitution is asserted. Content-only: no schema, RLS or RPC change.
-- Uses the optional section `table` object introduced by SEO-GRADE1.
-- Idempotent: a page already carrying the mechanical section is skipped.

create function pg_temp.seo_standard1_apply(
  p_slug text,
  p_marker text,
  p_title text,
  p_description text,
  p_sections jsonb,
  p_faq jsonb,
  p_sources jsonb
) returns void
language plpgsql
as $$
declare
  v_count integer;
begin
  update public.steel_knowledge_standard_pages p
  set
    seo_title=p_title,
    seo_description=p_description,
    editorial_sections=p_sections || p.editorial_sections,
    faq=p.faq || p_faq,
    source_references=p.source_references || p_sources,
    draft_payload=p.draft_payload || jsonb_build_object(
      'seo_title',p_title,
      'seo_description',p_description,
      'editorial_sections',p_sections || p.editorial_sections,
      'faq',p.faq || p_faq,
      'source_references',p.source_references || p_sources
    ),
    editorial_version=p.editorial_version+1,
    draft_version=greatest(p.draft_version,p.editorial_version+1),
    last_reviewed_at='2026-11-15'::date,
    updated_at=now()
  where p.slug=p_slug
    and p.page_status='published'
    and not exists (
      select 1
      from jsonb_array_elements(p.editorial_sections) s
      where s->>'heading'=p_marker
    );
  get diagnostics v_count=row_count;
  raise notice 'SEO-STANDARD1 %: % row(s) updated', p_slug, v_count;
end;
$$;

